INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Planung und Anforderungsanalyse > Prozess Anforderungsanalyse
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist der Prozess der Anforderungsanalyse unabhängig von den Kundenwünschen?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenwünsche sind zentraler Bestandteil"}, {"text": "Ja", "correct": false, "because": "Unabhängigkeit wäre kontraproduktiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Prozess der Anforderungsanalyse vollständig automatisiert ablaufen?', 2, '[{"text": "Nein", "correct": true, "because": "Menschliche Interaktion ist für Nuancen nötig"}, {"text": "Ja", "correct": false, "because": "Automatisierung deckt nicht alle Aspekte ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Prozess der Anforderungsanalyse immer schriftlich dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Dokumentation dient der Nachverfolgbarkeit"}, {"text": "Nein", "correct": false, "because": "Schriftlichkeit ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert der Prozess der Anforderungsanalyse keine Iterationen?', 2, '[{"text": "Nein", "correct": true, "because": "Iterationen sind oft nötig zur Verfeinerung"}, {"text": "Ja", "correct": false, "because": "Einmaligkeit ist unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Prozess der Anforderungsanalyse abgeschlossen, sobald die Hardware ausgewählt ist?', 2, '[{"text": "Nein", "correct": true, "because": "Analyse umfasst mehr als Hardware"}, {"text": "Ja", "correct": false, "because": "Hardware ist nur ein Teilaspekt"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird im Prozess der Anforderungsanalyse primär genutzt, um Kundenbedürfnisse zu ermitteln?', 3, '[{"text": "Interviews", "correct": true, "because": "Direkter Austausch liefert Details"}, {"text": "Benchmarking", "correct": false, "because": "Vergleich, kein Ermittlungstool"}, {"text": "Prototyping", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Prozesses der Anforderungsanalyse?', 2, '[{"text": "Klarstellung der Kundenanforderungen", "correct": true, "because": "Basis für Planung"}, {"text": "Festlegung des Budgets", "correct": false, "because": "Folge, kein Ziel"}, {"text": "Auswahl der Software", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Stakeholder hat im Prozess der Anforderungsanalyse die höchste Priorität?', 2, '[{"text": "Kunde", "correct": true, "because": "Dessen Wünsche stehen im Fokus"}, {"text": "Projektleiter", "correct": false, "because": "Koordiniert, definiert nicht"}, {"text": "Techniker", "correct": false, "because": "Umsetzt, nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument entsteht typischerweise aus dem Prozess der Anforderungsanalyse?', 2, '[{"text": "Pflichtenheft", "correct": true, "because": "Formuliert Anforderungen verbindlich"}, {"text": "Lastenheft", "correct": false, "because": "Vom Kunden, nicht Ergebnis"}, {"text": "Installationshandbuch", "correct": false, "because": "Späterer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt folgt direkt auf den Prozess der Anforderungsanalyse?', 3, '[{"text": "Erstellung des Pflichtenhefts", "correct": true, "because": "Formalisiert Ergebnisse"}, {"text": "Hardware-Beschaffung", "correct": false, "because": "Späterer Schritt"}, {"text": "Systeminstallation", "correct": false, "because": "Endphase"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Techniken werden im Prozess der Anforderungsanalyse häufig eingesetzt?', 4, '[{"text": "Interviews", "correct": true, "because": "Direkte Kundeninformation"}, {"text": "Fragebögen", "correct": true, "because": "Breite Datenbasis"}, {"text": "Beobachtung", "correct": true, "because": "Praxisnahe Erkenntnisse"}, {"text": "Regressionstests", "correct": false, "because": "Für Softwaretests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden im Prozess der Anforderungsanalyse betrachtet?', 3, '[{"text": "Funktionale Anforderungen", "correct": true, "because": "Was das System tun soll"}, {"text": "Nicht-funktionale Anforderungen", "correct": true, "because": "Qualität und Rahmen"}, {"text": "Hardware-Kompatibilität", "correct": true, "because": "Technische Basis"}, {"text": "Marketingstrategien", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können den Prozess der Anforderungsanalyse beeinträchtigen?', 3, '[{"text": "Unklare Kundenangaben", "correct": true, "because": "Fehlende Präzision"}, {"text": "Mangelnde Kommunikation", "correct": true, "because": "Verständnisprobleme"}, {"text": "Zeitdruck", "correct": true, "because": "Oberflächliche Analyse"}, {"text": "Hardware-Defekte", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen sind am Prozess der Anforderungsanalyse beteiligt?', 4, '[{"text": "Kunde", "correct": true, "because": "Liefert Anforderungen"}, {"text": "Fachinformatiker", "correct": true, "because": "Erhebt und strukturiert"}, {"text": "Projektmanager", "correct": true, "because": "Koordiniert Ablauf"}, {"text": "Lieferant", "correct": false, "because": "Später involviert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse liefert der Prozess der Anforderungsanalyse?', 3, '[{"text": "Anforderungskatalog", "correct": true, "because": "Liste der Bedürfnisse"}, {"text": "Systemvoraussetzungen", "correct": true, "because": "Technische Basis"}, {"text": "Pflichtenheft", "correct": true, "because": "Formale Dokumentation"}, {"text": "Rechnungsstellung", "correct": false, "because": "Wirtschaftlicher Aspekt"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Prozess der Anforderungsanalyse beginnt mit der Hardwareauswahl. b) Kundeninterviews sind ein zentraler Bestandteil.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Interviews ja, Hardware später"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Prozess der Anforderungsanalyse ist einmalig und nicht iterativ. b) Das Pflichtenheft ist ein mögliches Ergebnis.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Iterationen nötig, Pflichtenheft ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Prozess der Anforderungsanalyse umfasst nur technische Aspekte. b) Nicht-funktionale Anforderungen werden ebenfalls erhoben.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Auch nicht-technisch, b) richtig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Prozess der Anforderungsanalyse kann Zeitdruck ignorieren. b) Die Dokumentation ist optional.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Zeitdruck relevant, Dokumentation Pflicht"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Kunde definiert im Prozess der Anforderungsanalyse die technischen Details. b) Der Fachinformatiker strukturiert die Anforderungen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Kunde gibt Wünsche, FI strukturiert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

